/**
 * Frozen-node sampled-proximity parity + truth-table guard (PREPARATORY core).
 *
 * Feeds evalFrozenNodeProximity the SAME shared vector file the Python engine's
 * tests/test_alerts_frozen_node.py feeds _eval_frozen_node
 * (options_frozen_node_vectors.json — number/identity/case vectors generated by ONE
 * canonical algorithm). The two implementations MUST agree case for case: fired tri-state,
 * value, nextState and the language-neutral note markers. This is the drift guard.
 *
 * The trust law under test: the admission context arrives as a separate trusted ARGUMENT —
 * never from condition JSON; the row's created_at / condition._fnp are never enrollment or
 * prior-observation evidence; an absent/denied/unknown admission is an honest null that
 * never disarms and never updates state.
 */
import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { describe, expect, it } from "vitest";

import {
  evalFrozenNodeProximity,
  frozenNodeTargetFingerprint,
  fnpF64BeHex,
  fnpFormatInstantUtc,
  fnpInstantMicros,
  FNP_DEFAULT_WITHIN_PCT,
  FNP_QUALIFICATION,
  FNP_STATE_KEY,
  type FrozenNodeAdmissionContext,
  type FrozenNodeCond,
  type FrozenNodeEnvelope,
  type FrozenNodeQuote,
} from "../optionsAlerts";

type Obj = Record<string, unknown>;

/** One shared immutable fixture is consumed by both language suites. */
function loadVectors(): Obj {
  return JSON.parse(readFileSync(new URL("../../../tests/fixtures/options_frozen_node_vectors.json", import.meta.url), "utf8")) as Obj;
}

const V = loadVectors();
const vectors = V as unknown as {
  numbers: { value: number; beHex: string }[];
  instants: { input: string; micros: string; canonicalUtc: string }[];
  instantRejections: unknown[];
  targetVectors: { name: string; target: Obj; fingerprint: string }[];
  invalidTargets: { name: string; target: Obj }[];
  cases: {
    name: string;
    cond: Obj; envelope: Obj | null; admission: Obj | null; quote: Obj | null; prevState: Obj | null;
    expected: { fired: boolean | null; value: number | null; nextState: Obj | null;
                noteIncludes: string[]; noteExcludes: string[] };
  }[];
};

function deepEq(a: unknown, b: unknown): boolean {
  if (a === null || a === undefined || b === null || b === undefined) {
    return (a ?? null) === (b ?? null);
  }
  if (typeof a !== "object" || typeof b !== "object") return a === b;
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
    return a.every((x, i) => deepEq(x, b[i]));
  }
  const ka = Object.keys(a as Obj).sort();
  const kb = Object.keys(b as Obj).sort();
  if (ka.join(",") !== kb.join(",")) return false;
  return ka.every((k) => deepEq((a as Obj)[k], (b as Obj)[k]));
}

function run(c: (typeof vectors)["cases"][number]) {
  return evalFrozenNodeProximity(
    c.cond as unknown as FrozenNodeCond,
    c.envelope as unknown as FrozenNodeEnvelope | null,
    c.admission as unknown as FrozenNodeAdmissionContext | null,
    c.quote as unknown as FrozenNodeQuote | null,
    c.prevState as Obj | null,
  );
}

describe("frozen-node shared identity vectors", () => {
  it("renders finite doubles as IEEE-754 big-endian hex in both languages", () => {
    for (const n of vectors.numbers) {
      expect(fnpF64BeHex(n.value)).toBe(n.beHex);
    }
  });

  it("parses exact timezone-aware instants to UTC epoch microseconds and back", () => {
    for (const i of vectors.instants) {
      const micros = fnpInstantMicros(i.input);
      expect(micros, i.input).not.toBeNull();
      expect(micros!.toString()).toBe(i.micros);
      expect(fnpFormatInstantUtc(micros!)).toBe(i.canonicalUtc);
    }
  });

  it("rejects naive, impossible and non-exact clocks", () => {
    for (const bad of vectors.instantRejections) {
      expect(fnpInstantMicros(bad), JSON.stringify(bad)).toBeNull();
    }
  });

  it("fingerprints every target variant identically to Python", () => {
    for (const t of vectors.targetVectors) {
      expect(frozenNodeTargetFingerprint(t.target), t.name).toBe(t.fingerprint);
    }
  });

  it("refuses to fingerprint a malformed target", () => {
    for (const t of vectors.invalidTargets) {
      expect(frozenNodeTargetFingerprint(t.target), t.name).toBeNull();
    }
  });

  it("exposes the documented constants", () => {
    expect(FNP_STATE_KEY).toBe("_fnp");
    expect(FNP_QUALIFICATION).toBe("observed_partial");
    expect(FNP_DEFAULT_WITHIN_PCT).toBe(0.25);
  });
});

describe("frozen-node shared truth-table vectors", () => {
  for (const c of vectors.cases) {
    it(`${c.name} (fired=${JSON.stringify(c.expected.fired)})`, () => {
      const r = run(c);
      // fired mirrors EvalResult: null = cannot evaluate (never disarms).
      expect(r.fired ?? null, `${c.name}: note=${r.note}`).toBe(c.expected.fired ?? null);
      expect(r.value ?? null).toBe(c.expected.value ?? null);
      expect(deepEq(r.nextState ?? null, c.expected.nextState ?? null),
             `${c.name}: nextState ${JSON.stringify(r.nextState)}`).toBe(true);
      if (c.expected.fired === true) {
        for (const inc of c.expected.noteIncludes) {
          expect(r.note, c.name).toContain(inc);
        }
        for (const exc of c.expected.noteExcludes) {
          expect(r.note, c.name).not.toContain(exc);
        }
        // Display-tier law: no banned vocabulary in a delivered note.
        for (const banned of ["signal", "buy", "sell", "validated", "strongest"]) {
          expect(r.note.toLowerCase(), c.name).not.toContain(banned);
        }
      }
      if (c.expected.fired === null) {
        // A null is honest: it says WHY, and it never silently invents a state.
        expect(r.note.length, c.name).toBeGreaterThan(0);
      }
    });
  }
});

describe("frozen-node trust law (language-specific, not vector-encodable)", () => {
  const baseTarget = vectors.targetVectors[0].target;
  const ARMING = "2026-09-08T13:30:00Z";
  const EVAL_AT = "2026-09-08T14:00:00Z";
  const Q1 = "2026-09-08T13:45:00Z";
  const fp = frozenNodeTargetFingerprint(baseTarget)!;
  const cond = { type: "opt_frozen_node_proximity", root: "SPY", target: baseTarget } as unknown as FrozenNodeCond;
  const envelope = { principal: "user-42", createdAt: "2026-09-08T13:25:00Z", evaluationAt: EVAL_AT };
  const rights = { allowed: true, policy_version: "frozen-node-admission/2026-09", checked_at: EVAL_AT };
  const admission = (priorState: Obj | null): FrozenNodeAdmissionContext =>
    ({ principal: "user-42", createdAt: "2026-09-08T13:25:00Z", armingEpoch: ARMING,
       evaluationAt: EVAL_AT, action: "frozen_node_proximity", target: baseTarget,
       rights, priorState }) as unknown as FrozenNodeAdmissionContext;
  const quote = (spot: number): FrozenNodeQuote =>
    ({ spot, asof: Q1, basis: "DELAYED_15M" }) as FrozenNodeQuote;

  it("refuses non-finite thresholds that JSON vectors cannot carry", () => {
    for (const within_pct of [Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY, -0.5]) {
      const r = evalFrozenNodeProximity({ ...cond, within_pct }, envelope, admission(null), quote(620), null);
      expect(r.fired).toBeNull();
      expect(r.note).toContain("threshold");
    }
  });

  it("a planted admission blob inside the condition jsonb grants nothing", () => {
    const spoofed = {
      ...cond,
      admission: admission({ targetFingerprint: fp, armingEpoch: ARMING, lastQuoteAt: Q1, inside: false, withinPct: .25, lastQuoteBasis: "DELAYED_15M" }),
      rights,
      allowed: true,
      armingEpoch: ARMING,
    } as unknown as FrozenNodeCond;
    const r = evalFrozenNodeProximity(spoofed, envelope, null, quote(620), null);
    expect(r.fired).toBeNull();
    expect(r.note).toContain("admission unavailable");
  });

  it("an absent reader never disarms and never invents state", () => {
    const row = { targetFingerprint: fp, armingEpoch: ARMING, lastQuoteAt: Q1, inside: false, withinPct: .25, lastQuoteBasis: "DELAYED_15M" };
    const r = evalFrozenNodeProximity(cond, envelope, null, quote(620), row);
    expect(r.fired).toBeNull();
    expect(deepEq(r.nextState as Obj, row)).toBe(true);
  });

  it("a fired note discloses a delayed basis and keeps the frozen level", () => {
    const prior = { targetFingerprint: fp, armingEpoch: ARMING, lastQuoteAt: "2026-09-08T13:44:00Z", inside: false, withinPct: .25, lastQuoteBasis: "DELAYED_15M" };
    const r = evalFrozenNodeProximity(cond, envelope, admission(prior), quote(620), prior);
    expect(r.fired).toBe(true);
    expect(r.note).toContain("15-minute-delayed quote");
    expect(r.note).toContain("620");
    expect(r.note).not.toContain("630");
    expect(r.note).toContain("as of 2026-09-08T13:45:00Z");
    expect(r.note).toContain("intraday");
  });

  it("state bindings are byte-identical across languages for the same instant spellings", () => {
    // -04:00 offset and Z spelling of the same instant must fingerprint identically.
    const offset = frozenNodeTargetFingerprint({
      ...baseTarget, availableAt: "2026-09-08T09:15:00-04:00",
    });
    const utc = frozenNodeTargetFingerprint({ ...baseTarget, availableAt: "2026-09-08T13:15:00Z" });
    expect(offset).toBe(utc);
  });
});


describe("principal canonical-identity counterexample", () => {
  it("matches native SHA-256 over UTF-8 length-prefixed full target tokens", () => {
    for (const item of vectors.targetVectors) {
      const t = item.target as unknown as FrozenNodeAdmissionContext["target"];
      const clocks = Object.keys(t.sourceBinding.clocks).sort();
      const members = t.members.map(m => `${m.expiry}\x1f${m.right}\x1f${fnpF64BeHex(m.strike)}`).sort();
      const tokens = ["opt_frozen_node_target/v1", t.root, t.securityId, t.sourceSession, t.sourceKey,
        t.definitionKey, t.scopeKey, String(fnpInstantMicros(t.availableAt)), t.sourceBinding.inputSha256,
        t.sourceBinding.populationId, t.sourceBinding.sourceRef, "clocks", String(clocks.length),
        ...clocks.flatMap(k => [k, String(fnpInstantMicros(t.sourceBinding.clocks[k]))]), "members", String(members.length),
        ...members.flatMap(m => ["member", m]), "price", fnpF64BeHex(t.price)!, "observed_partial"];
      const encoded = tokens.map(token => `${Buffer.byteLength(token, "utf8")}:${token}`).join("");
      expect(frozenNodeTargetFingerprint(t), item.name).toBe(createHash("sha256").update(encoded).digest("hex"));
    }
  });
});
